"""Default pluggy hook implementations for the Rasa CLI and runtime.

Registers CLI subcommands, wires endpoints/tracing/metrics at startup, and
provides the default tracker-store factory. Scoped imports inside each hook
avoid circular dependencies with the rest of ``rasa``.
"""

import argparse
from pathlib import Path
from typing import TYPE_CHECKING, List, Optional, Text, Union

import pluggy

# IMPORTANT: do not import anything from rasa here - use scoped imports
#  this avoids circular imports, as the hooks are used in different places
#  across the codebase.

if TYPE_CHECKING:
    from rasa.cli import SubParsersAction
    from rasa.core.brokers.broker import EventBroker
    from rasa.core.tracker_stores.tracker_store import TrackerStore
    from rasa.shared.core.domain import Domain
    from rasa.utils.endpoints import EndpointConfig

hookimpl = pluggy.HookimplMarker("rasa")


@hookimpl
def refine_cli(
    subparsers: "SubParsersAction",
    parent_parsers: List[argparse.ArgumentParser],
) -> None:
    """Register Rasa Pro CLI subcommands (e2e, DU test, studio, inspect, …)."""
    from rasa.cli import dialogue_understanding_test, e2e_test, inspect, markers
    from rasa.cli import license as license_cli
    from rasa.cli.studio import studio

    e2e_test.add_subparser(subparsers, parent_parsers)
    dialogue_understanding_test.add_subparser(subparsers, parent_parsers)
    studio.add_subparser(subparsers, parent_parsers)
    license_cli.add_subparser(subparsers, parent_parsers)
    markers.add_subparser(subparsers, parent_parsers)
    inspect.add_subparser(subparsers, parent_parsers)
    return None


@hookimpl
def configure_commandline(cmdline_arguments: argparse.Namespace) -> Optional[Text]:
    """Resolve endpoints and configure backend tracing, metrics, and Langfuse.

    Mantle projects load tracing (Langfuse and OTLP/Jaeger) and OTLP metrics
    only from ``integrations.yml``. Runs even when no ``--endpoints`` path is
    given so integrations-only projects still get observability.

    Mantle reads integrations from ``integrations.yml``. An ``endpoints.yml``
    at the project root or passed through ``--endpoints`` is ignored with a
    warning. CALM v1 keeps reading ``endpoints.yml``.
    """
    from rasa.cli import x as rasa_x
    from rasa.cli.project_env import resolve_project_dir
    from rasa.shared.engine_version import is_mantle_cli_context
    from rasa.tracing.process_observability import (
        ObservabilitySettings,
        configure_process_observability,
    )

    endpoints_file = None

    if cmdline_arguments.func.__name__ == "rasa_x":
        _, endpoints_file = rasa_x._get_credentials_and_endpoints_paths(
            cmdline_arguments
        )
    elif "endpoints" in cmdline_arguments:
        endpoints_file = cmdline_arguments.endpoints

    project_root = resolve_project_dir(getattr(cmdline_arguments, "project_path", None))
    # Same choice as channel loading. A Mantle archive whose skills are not on
    # disk selects Mantle here; a layout that really disagrees still wins.
    is_mantle = is_mantle_cli_context(
        project_root=project_root,
        model_path=getattr(cmdline_arguments, "model", None),
    )
    if is_mantle:
        _warn_if_endpoints_file_for_mantle(
            project_root, cmdline_arguments, endpoints_file
        )
        endpoints_file = None

    configure_process_observability(
        ObservabilitySettings(
            project_root=str(project_root),
            endpoints_file=endpoints_file,
            is_mantle=is_mantle,
            langfuse_environment_name=getattr(
                cmdline_arguments, "langfuse_environment_name", None
            ),
        )
    )

    return endpoints_file


@hookimpl
def init_telemetry(endpoints_file: Optional[Text]) -> None:
    """Send endpoint-configuration traits to product telemetry."""
    import rasa.telemetry

    rasa.telemetry.identify_endpoint_config_traits(endpoints_file)


@hookimpl
def init_managers(
    endpoints_file: Optional[Text],
    model_path: Optional[Text] = None,
) -> None:
    """Load the secrets manager for this project.

    Mantle reads ``secrets_manager:`` from ``integrations.yml``. ``VAULT_*``
    environment variables
    still merge with that block. CALM keeps reading ``endpoints.yml``.
    The project directory is ``RASA_PROJECT_FOLDER`` when that is set, and
    the working directory otherwise. *model_path* is the startup ``--model``
    archive: a Mantle archive beside ``integrations.yml`` and no skills
    directory is Mantle even though the on-disk layout is incomplete.
    """
    from rasa.cli.project_env import resolve_project_dir
    from rasa.core.secrets_manager.factory import load_secret_manager
    from rasa.core.secrets_manager.secret_manager import SecretsManagerProvider
    from rasa.shared.engine_version import is_mantle_cli_context

    # Lookup errors raised after this returns still need the startup archive.
    SecretsManagerProvider.startup_model_path = model_path
    root = resolve_project_dir()
    if is_mantle_cli_context(project_root=root, model_path=model_path):
        from rasa.mantle.config.runtime_endpoints import (
            load_integration_secrets_manager,
        )

        settings = load_integration_secrets_manager(root)
        endpoint_config = (
            settings.as_endpoint_config() if settings is not None else None
        )
        load_secret_manager(endpoint_config=endpoint_config)
        return

    load_secret_manager(endpoints_file)


@hookimpl
def create_tracker_store(
    endpoint_config: Union["TrackerStore", "EndpointConfig"],
    domain: "Domain",
    event_broker: Optional["EventBroker"],
) -> "TrackerStore":
    """Return a tracker store, wrapping ``EndpointConfig`` with auth retry."""
    from rasa.core.tracker_stores.auth_retry_tracker_store import AuthRetryTrackerStore
    from rasa.utils.endpoints import EndpointConfig

    if isinstance(endpoint_config, EndpointConfig):
        return AuthRetryTrackerStore(
            endpoint_config=endpoint_config, domain=domain, event_broker=event_broker
        )
    return endpoint_config


def _warn_if_endpoints_file_for_mantle(
    project_root: Path,
    cmdline_arguments: argparse.Namespace,
    endpoints_file: Optional[Text],
) -> None:
    """Warn when a Mantle project still has an endpoints file or flag.

    ``endpoints.yml`` at the project root is ignored. An explicit
    ``--endpoints`` path is also ignored, even when missing. The CLI default is
    not treated as the flag.
    """
    from rasa.cli.arguments.default_arguments import ENDPOINTS_EXPLICITLY_SET
    from rasa.mantle.config.runtime_endpoints import warn_endpoints_file_ignored
    from rasa.shared.constants import DEFAULT_ENDPOINTS_PATH

    project_endpoints = project_root / DEFAULT_ENDPOINTS_PATH
    if project_endpoints.is_file():
        warn_endpoints_file_ignored()
    if (
        getattr(cmdline_arguments, ENDPOINTS_EXPLICITLY_SET, False)
        and endpoints_file is not None
    ):
        warn_endpoints_file_ignored()
